package money

import (
	"strconv"
	"strings"
)

// FormatPrice renders cents as a dollar amount, e.g. 1234 -> "$12.34",
// -5 -> "-$0.05".
func FormatPrice(cents int64) string {
	var u uint64
	neg := cents < 0
	if neg {
		u = uint64(-(cents + 1)) + 1
	} else {
		u = uint64(cents)
	}

	dollars := u / 100
	rem := u % 100

	var b strings.Builder
	if neg {
		b.WriteByte('-')
	}
	b.WriteByte('$')
	b.WriteString(strconv.FormatUint(dollars, 10))
	b.WriteByte('.')
	if rem < 10 {
		b.WriteByte('0')
	}
	b.WriteString(strconv.FormatUint(rem, 10))
	return b.String()
}

